// The iPhone launcher's look, taken from the HTML preview (Launcher_preview): its colors, its exact sizes (in
// points: the preview's pixels), its images, the animated background and the small controls (switch, segments,
// menu, buttons). iOS only: the Mac launcher does not use this file. Launcher.swift builds the screens from these.

#if !os(macOS)
import SwiftUI
import UIKit

enum PhoneStyle {
    static let accent = Color(red: 204 / 255, green: 43 / 255, blue: 43 / 255)  // #cc2b2b, the red of Play and Back
    static let muted = Color.white.opacity(0.6)
    static let line = Color.white.opacity(0.12)
    static let card = Color.white.opacity(0.07)
    static let subtitle = Color(red: 208 / 255, green: 208 / 255, blue: 208 / 255)  // #d0d0d0, the logo's gray
    static let found = Color(red: 52 / 255, green: 199 / 255, blue: 89 / 255)  // #34c759
    static let warning = Color(red: 1, green: 179 / 255, blue: 64 / 255)  // #ffb340
    static let link = Color(red: 1, green: 107 / 255, blue: 107 / 255)  // #ff6b6b
    static let resetRed = Color(red: 1, green: 138 / 255, blue: 128 / 255)  // #ff8a80
    static let resetGreen = Color(red: 126 / 255, green: 224 / 255, blue: 138 / 255)  // #7ee08a
    static let profile = URL(string: "https://github.com/ke619")!

    static func font(_ size: CGFloat, _ weight: Font.Weight = .regular) -> Font {
        Font.system(size: size, weight: weight)
    }
}

// The images of the preview, kept as text so the build needs no extra files.
enum PhoneArt {
    static let logo: UIImage? = decode(logoPNG)
    static let wordmark: UIImage? = decode(wordmarkPNG)
    static let github: UIImage? = decode(githubPNG)

    private static func decode(_ base64: String) -> UIImage? {
        guard let data = Data(base64Encoded: base64) else { return nil }
        return UIImage(data: data)
    }

    private static let logoPNG = ""
    private static let wordmarkPNG = ""
    private static let githubPNG = ""
}

struct PhoneImage: View {
    let image: UIImage?
    var body: some View {
        if let image = image {
            Image(uiImage: image).resizable().scaledToFit()
        } else {
            Color.clear
        }
    }
}

// ---- The backdrop: the dark gradient with a faint glow, as the preview's #phone ----
struct PhoneBackdrop: View {
    var body: some View {
        GeometryReader { geo in
            ZStack {
                LinearGradient(
                    colors: [Color(red: 28 / 255, green: 28 / 255, blue: 36 / 255),
                             Color(red: 8 / 255, green: 8 / 255, blue: 13 / 255)],
                    startPoint: .top, endPoint: .bottom)
                glow(geo.size)
            }
            .clipped()
        }
    }

    // radial-gradient(ellipse 60% 70% at 50% 42%, white at 7%, transparent)
    private func glow(_ size: CGSize) -> some View {
        let rx = size.width * 0.6
        let ry = size.height * 0.7
        return RadialGradient(colors: [Color.white.opacity(0.07), Color.white.opacity(0)],
                              center: .center, startRadius: 0, endRadius: rx)
            .frame(width: rx * 2, height: rx * 2)
            .scaleEffect(x: 1, y: ry / rx)
            .position(x: size.width * 0.5, y: size.height * 0.42)
    }
}

// ---- The animated background: thin lines along three directions that draw in and fade out, a node where two
// cross (pulsing, with a ring that spreads) and a small light travelling along some lines. The same lines as the
// preview (its random numbers, in the same order), drawn at 30 frames a second; still when Reduce Motion is on. ----
private struct BGLine {
    let x1: Double, y1: Double, x2: Double, y2: Double
    let opacity: Double
    let duration: Double
    let delay: Double
    let travels: Bool
    let travelDuration: Double
    let travelBegin: Double
}

private struct BGNode {
    let x: Double, y: Double
    let pulseDelay: Double
    let pingDelay: Double
}

private struct BGScene {
    static let shared = BGScene()
    var lines: [BGLine] = []
    var nodes: [BGNode] = []

    init() {
        var seed: Int64 = 9
        func random() -> Double {
            seed = seed * 16807 % 2147483647
            return Double(seed) / 2147483647.0
        }
        func tenth(_ n: Double) -> Double { (n * 10).rounded() / 10 }  // toFixed(1)

        let directions: [(Double, Double)] = [(0, -1), (0.866, -0.5), (0.866, 0.5)]
        var raw: [(x1: Double, y1: Double, x2: Double, y2: Double)] = []
        for (cx, cy) in [(165.0, 205.0), (690.0, 185.0)] {
            for (dx, dy) in directions {
                for side in [-1.0, 1.0] {
                    let o = side * (30 + random() * 70)
                    let len = 190 + random() * 150
                    let sx = cx - dy * o + (random() - 0.5) * 40
                    let sy = cy + dx * o + (random() - 0.5) * 40
                    raw.append((sx - dx * len / 2, sy - dy * len / 2, sx + dx * len / 2, sy + dy * len / 2))
                }
            }
        }
        for (i, l) in raw.enumerated() {
            let duration = Double(Int(12 + random() * 6))
            let delay = Double(Int(random() * 14))
            let opacity = tenth(0.1 + random() * 0.08)
            var travels = false
            var travelDuration = 1.0
            var travelBegin = 0.0
            if i % 3 == 0 {
                travels = true
                travelDuration = Double(Int(7 + random() * 5))
                travelBegin = Double(Int(random() * 8))
            }
            lines.append(BGLine(x1: tenth(l.x1), y1: tenth(l.y1), x2: tenth(l.x2), y2: tenth(l.y2),
                                opacity: opacity, duration: duration, delay: delay,
                                travels: travels, travelDuration: travelDuration, travelBegin: travelBegin))
        }
        // where two lines cross
        func cross(_ a: (x1: Double, y1: Double, x2: Double, y2: Double),
                   _ b: (x1: Double, y1: Double, x2: Double, y2: Double)) -> (Double, Double)? {
            let d = (a.x2 - a.x1) * (b.y2 - b.y1) - (a.y2 - a.y1) * (b.x2 - b.x1)
            if abs(d) < 1e-6 { return nil }
            let t = ((b.x1 - a.x1) * (b.y2 - b.y1) - (b.y1 - a.y1) * (b.x2 - b.x1)) / d
            let u = ((b.x1 - a.x1) * (a.y2 - a.y1) - (b.y1 - a.y1) * (a.x2 - a.x1)) / d
            if t > 0 && t < 1 && u > 0 && u < 1 { return (a.x1 + t * (a.x2 - a.x1), a.y1 + t * (a.y2 - a.y1)) }
            return nil
        }
        for i in 0..<raw.count {
            for j in (i + 1)..<raw.count {
                if let p = cross(raw[i], raw[j]), random() < 0.55 {
                    let pulse = Double(Int(random() * 6))
                    let ping = Double(Int(random() * 6))
                    nodes.append(BGNode(x: tenth(p.0), y: tenth(p.1), pulseDelay: pulse, pingDelay: ping))
                }
            }
        }
    }
}

struct PhoneBackground: View {
    @State private var started = Date()
    private let calm = UIAccessibility.isReduceMotionEnabled

    var body: some View {
        GeometryReader { geo in
            TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: calm)) { timeline in
                Canvas { context, size in
                    drawScene(context, size, timeline.date.timeIntervalSince(started))
                }
            }
            .mask { fade(geo.size) }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }

    // mask-image: radial-gradient(ellipse 25% 46% at 50% 52%, transparent 30%, black 100%)
    private func fade(_ size: CGSize) -> some View {
        let rx = size.width * 0.25
        let ry = size.height * 0.46
        return ZStack {
            Color.black
            RadialGradient(stops: [.init(color: .black, location: 0), .init(color: .black, location: 0.3),
                                   .init(color: .clear, location: 1)],
                           center: .center, startRadius: 0, endRadius: rx)
                .frame(width: rx * 2, height: rx * 2)
                .scaleEffect(x: 1, y: ry / rx)
                .position(x: size.width * 0.5, y: size.height * 0.52)
                .blendMode(.destinationOut)
        }
        .frame(width: size.width, height: size.height)
        .compositingGroup()
    }

    private func ease(_ x: Double) -> Double {
        let c = min(max(x, 0), 1)
        return c * c * (3 - 2 * c)
    }

    private func easeOut(_ x: Double) -> Double {
        let c = min(max(x, 0), 1)
        return 1 - (1 - c) * (1 - c)
    }

    private func drawScene(_ context: GraphicsContext, _ size: CGSize, _ t: Double) {
        // the preview's 852 x 393 picture, scaled to cover the screen
        let scale = max(size.width / 852, size.height / 393)
        let ox = (size.width - 852 * scale) / 2
        let oy = (size.height - 393 * scale) / 2
        func point(_ x: Double, _ y: Double) -> CGPoint { CGPoint(x: ox + x * scale, y: oy + y * scale) }
        func dot(_ c: CGPoint, _ r: Double) -> Path {
            Path(ellipseIn: CGRect(x: c.x - r, y: c.y - r, width: r * 2, height: r * 2))
        }
        let scene = BGScene.shared

        for line in scene.lines {
            var shown = 1.0
            var alpha = 1.0
            if !calm {
                let p = fmod(t + line.delay, line.duration) / line.duration
                if p < 0.2 {
                    shown = ease(p / 0.2)
                    alpha = shown
                } else if p >= 0.78 {
                    alpha = 1 - ease((p - 0.78) / 0.22)
                }
            }
            if shown > 0.001 && alpha > 0.001 {
                var path = Path()
                path.move(to: point(line.x1, line.y1))
                path.addLine(to: point(line.x1 + (line.x2 - line.x1) * shown, line.y1 + (line.y2 - line.y1) * shown))
                context.stroke(path, with: .color(Color.white.opacity(line.opacity * alpha)), lineWidth: 0.7 * scale)
            }
            if line.travels && !calm {
                let f = fmod(t + line.travelBegin, line.travelDuration) / line.travelDuration
                let c = point(line.x1 + (line.x2 - line.x1) * f, line.y1 + (line.y2 - line.y1) * f)
                context.fill(dot(c, 1.7 * scale), with: .color(Color.white.opacity(0.5)))
            }
        }

        for node in scene.nodes {
            let c = point(node.x, node.y)
            var pulse = 1.0
            if !calm {
                let p = fmod(t + node.pulseDelay, 5) / 5
                pulse = p < 0.5 ? 0.35 + 0.65 * ease(p / 0.5) : 0.35 + 0.65 * (1 - ease((p - 0.5) / 0.5))
            }
            context.fill(dot(c, 2 * scale), with: .color(Color.white.opacity(0.4 * pulse)))
            if !calm {
                let q = fmod(t + node.pingDelay, 5) / 5
                let e = easeOut(q)
                let grow = 1 + 3.5 * e
                context.stroke(dot(c, 2 * grow * scale), with: .color(Color.white.opacity(0.4 * 0.7 * (1 - e))),
                               lineWidth: 0.6 * grow * scale)
            }
        }
    }
}

// ---- The small controls, at the preview's sizes ----

// PLAY and BACK: the red capsule (.play).
struct PhonePlayStyle: ButtonStyle {
    let size: CGFloat
    let horizontal: CGFloat
    let vertical: CGFloat
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .font(PhoneStyle.font(size, .heavy))
            .tracking(size * 0.22)
            .foregroundColor(.white)
            .padding(.horizontal, horizontal)
            .padding(.vertical, vertical)
            .background(Capsule().fill(PhoneStyle.accent))
            .opacity(configuration.isPressed ? 0.8 : 1)
    }
}

// Settings on the home screen (.ghost).
struct PhoneGhostStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .font(PhoneStyle.font(13, .semibold))
            .foregroundColor(.white)
            .padding(.horizontal, 26)
            .padding(.vertical, 8)
            .background(Capsule().fill(Color.white.opacity(0.1)))
            .overlay(Capsule().stroke(PhoneStyle.line, lineWidth: 1))
            .opacity(configuration.isPressed ? 0.7 : 1)
    }
}

// The small outlined button of the rows (.btn2), in white, red or green.
struct PhonePillStyle: ButtonStyle {
    var color: Color = .white
    var border: Color = PhoneStyle.line
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .font(PhoneStyle.font(13))
            .foregroundColor(color)
            .padding(.horizontal, 16)
            .padding(.vertical, 6)
            .background(Capsule().fill(Color.white.opacity(0.1)))
            .overlay(Capsule().stroke(border, lineWidth: 1))
            .opacity(configuration.isPressed ? 0.7 : 1)
    }
}

// The switch (.tog): 42 x 26, red when on. A real Toggle with this style, so VoiceOver still reads it as one.
struct PhoneToggleStyle: ToggleStyle {
    func makeBody(configuration: Configuration) -> some View {
        Button { configuration.isOn.toggle() } label: {
            HStack(spacing: 12) {
                configuration.label
                    .font(PhoneStyle.font(13))
                    .foregroundColor(.white)
                    .frame(maxWidth: .infinity, alignment: .leading)
                Capsule()
                    .fill(configuration.isOn ? PhoneStyle.accent : Color.white.opacity(0.2))
                    .frame(width: 42, height: 26)
                    .overlay(alignment: .leading) {
                        Circle().fill(Color.white).frame(width: 22, height: 22)
                            .offset(x: configuration.isOn ? 18 : 2)
                    }
                    .animation(.easeOut(duration: 0.15), value: configuration.isOn)
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityValue(configuration.isOn ? "On" : "Off")
    }
}

// Choices side by side (.seg).
struct PhoneSegments<Value: Hashable>: View {
    let options: [(label: String, value: Value)]
    @Binding var selection: Value

    var body: some View {
        HStack(spacing: 0) {
            ForEach(options.indices, id: \.self) { i in
                segment(i)
            }
        }
        .padding(2)
        .background(RoundedRectangle(cornerRadius: 8).fill(Color.white.opacity(0.1)))
    }

    private func segment(_ i: Int) -> some View {
        let on = options[i].value == selection
        return Button { selection = options[i].value } label: {
            Text(options[i].label)
                .font(PhoneStyle.font(13, .medium))
                .foregroundColor(on ? .white : PhoneStyle.muted)
                .lineLimit(1)
                .fixedSize()
                .padding(.horizontal, 9)
                .padding(.vertical, 4)
                .background(RoundedRectangle(cornerRadius: 6).fill(on ? Color.white.opacity(0.26) : Color.clear))
        }
        .buttonStyle(.plain)
        .accessibilityAddTraits(on ? .isSelected : [])
    }
}

// A drop-down (the preview's select).
struct PhoneMenu<Value: Hashable>: View {
    let options: [(label: String, value: Value)]
    @Binding var selection: Value

    var body: some View {
        Menu {
            ForEach(options.indices, id: \.self) { i in
                Button {
                    selection = options[i].value
                } label: {
                    if options[i].value == selection {
                        Label(options[i].label, systemImage: "checkmark")
                    } else {
                        Text(options[i].label)
                    }
                }
            }
        } label: {
            HStack(spacing: 6) {
                Text(current)
                    .font(PhoneStyle.font(13))
                    .lineLimit(1)
                Image(systemName: "chevron.up.chevron.down")
                    .font(.system(size: 9, weight: .semibold))
            }
            .foregroundColor(.white)
            .padding(.horizontal, 8)
            .padding(.vertical, 5)
            .background(RoundedRectangle(cornerRadius: 8).fill(Color.white.opacity(0.12)))
        }
    }

    private var current: String {
        options.first { $0.value == selection }?.label ?? ""
    }
}

// The text box (.in).
struct PhoneTextField: View {
    let prompt: String
    @Binding var text: String
    var body: some View {
        TextField("", text: $text, prompt: Text(prompt).foregroundColor(Color.white.opacity(0.35)))
            .font(PhoneStyle.font(13))
            .foregroundColor(.white)
            .autocorrectionDisabled()
            .textInputAutocapitalization(.never)
            .padding(.horizontal, 8)
            .padding(.vertical, 5)
            .frame(width: 220)
            .background(RoundedRectangle(cornerRadius: 8).fill(Color.white.opacity(0.12)))
    }
}

// A row of a card (.row): its label at the left, its control at the right; at least 38 high.
struct PhoneRow<Content: View>: View {
    let label: String
    let content: Content
    init(_ label: String, @ViewBuilder content: () -> Content) {
        self.label = label
        self.content = content()
    }
    var body: some View {
        HStack(spacing: 12) {
            Text(label)
                .font(PhoneStyle.font(13))
                .foregroundColor(.white)
                .frame(maxWidth: .infinity, alignment: .leading)
            content
        }
        .padding(.horizontal, 14)
        .padding(.vertical, 8)
        .frame(minHeight: 38)
    }
}

// A row with something of its own inside (.row without a label).
struct PhoneFreeRow<Content: View>: View {
    let content: Content
    init(@ViewBuilder content: () -> Content) { self.content = content() }
    var body: some View {
        HStack(spacing: 12) {
            content
        }
        .padding(.horizontal, 14)
        .padding(.vertical, 8)
        .frame(maxWidth: .infinity, minHeight: 38, alignment: .leading)
    }
}

// The rounded card (.card) holding rows, a thin line between two rows.
struct PhoneCard: View {
    let rows: [AnyView]
    var body: some View {
        VStack(spacing: 0) {
            ForEach(rows.indices, id: \.self) { i in
                if i > 0 {
                    Rectangle().fill(PhoneStyle.line).frame(height: 1)
                }
                rows[i]
            }
        }
        .background(PhoneStyle.card)
        .clipShape(RoundedRectangle(cornerRadius: 14))
    }
}

// The small print under a card (.foot).
struct PhoneFoot: View {
    let text: String
    var body: some View {
        Text(text)
            .font(PhoneStyle.font(11))
            .foregroundColor(PhoneStyle.muted)
            .lineSpacing(1.7)
            .fixedSize(horizontal: false, vertical: true)
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding(.horizontal, 6)
            .padding(.top, 6)
            .padding(.bottom, 12)
    }
}

// A tab of the list at the left (nav b).
struct PhoneTab: View {
    let title: String
    let selected: Bool
    let action: () -> Void
    var body: some View {
        Button(action: action) {
            Text(title)
                .font(PhoneStyle.font(13, .semibold))
                .foregroundColor(selected ? .white : PhoneStyle.muted)
                .padding(.horizontal, 12)
                .frame(maxWidth: .infinity, minHeight: 33.5, maxHeight: 33.5, alignment: .leading)
                .background(RoundedRectangle(cornerRadius: 9).fill(selected ? Color.white.opacity(0.14) : Color.clear))
                .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityAddTraits(selected ? .isSelected : [])
    }
}

// The progress bar of "Compiling shaders".
struct PhoneProgressBar: View {
    let fraction: Double
    var body: some View {
        GeometryReader { geo in
            ZStack(alignment: .leading) {
                Capsule().fill(Color.white.opacity(0.2))
                Capsule().fill(PhoneStyle.accent)
                    .frame(width: geo.size.width * CGFloat(min(max(fraction, 0), 1)))
            }
        }
        .frame(height: 6)
    }
}
#endif
